class Fake:
    "A stand-in model for tests: `Fake({'grade': {...}, 'question': {...}})`."
    def __init__(self, rules:dict=None, dflt='{}'): self.rules, self.dflt, self.calls = rules or {}, dflt, []
    def __call__(self, prompt, sp=''):
        self.calls.append((prompt, sp))
        r = next((v for k, v in self.rules.items() if k in prompt or k in sp), self.dflt)
        if callable(r): r = r(prompt, sp)
        return r if isinstance(r, str) else json.dumps(r)

# %% ../nbs/02_llm.ipynb #5452d193
TASKS = ('question', 'grade', 'hint', 'lesson', 'extract')
TOKENS = dict(question=4096, grade=2048, hint=512, lesson=2048, extract=4096)   # the reply cap of each task, when the settings give none
TOKENS_MAX = 32768

def check_tokens(v) -> int|str:
    "A reply cap from the Settings page: a whole number from 1 to `TOKENS_MAX`, or '' for the default. Raise `ValueError` for another value."
    v = str(v).strip()
    if not v: return ''
    if not v.isdigit() or not 1 <= int(v) <= TOKENS_MAX:
        raise ValueError(f'Type a whole number from 1 to {TOKENS_MAX}, or make the box empty to use the default.')
    return int(v)

