def _settings(): return __import__('abhyasa.voice', fromlist=['settings']).settings()

class Router:
    "The tutor's model: a default `ask`, and one model for each task that the settings name."
    def __init__(self, dflt, models=None, tokens=None):
        self.dflt, self.model = dflt, getattr(dflt, 'model', '')
        self.models = models or (lambda: _settings().get('models', {}))
        self.tokens = tokens or (lambda: _settings().get('tokens', {}))
    def __call__(self, prompt, sp=''): return self.dflt(prompt, sp)
    def name(self, task:str) -> str:
        "The model for `task`, or '' for the default."
        return (self.models() or {}).get(task) or ''
    def cap(self, task:str) -> int:
        "The reply cap of `task`: the saved value, else `TOKENS[task]`. A bad saved value gives the default."
        try: return check_tokens((self.tokens() or {}).get(task, '')) or TOKENS[task]
        except ValueError: return TOKENS[task]
    def for_(self, task:str, name:str=None):
        "The `ask` for `task` on `name`, else on the model of the settings, else on the default."
        n = self.name(task) if name is None else name
        if hasattr(self.dflt, 'via'): return self.dflt.via(task, n, self.cap(task))
        return model_ask(n) if n else self.dflt
    def warm(self):
        "Start the backend of each task in a background thread, with no model call. Returns the thread, or None."
        if not hasattr(self.dflt, 'warm'): return None
        t = threading.Thread(target=lambda: self.dflt.warm({k: self.name(k) for k in TASKS}), daemon=True)
        t.start()
        return t

def for_task(ask, task:str):
    "The `ask` for `task` when `ask` routes by task, else `ask` itself."
    return ask.for_(task) if hasattr(ask, 'for_') else ask

